/** The artist profile for a locale, falling back to English. */
export function artistProfile(name?: string, locale: Locale = 'en'): ArtistProfile | undefined {
  if (!name) return undefined;
  return (
    (locale === 'de' && ARTIST_PROFILES_DE[name]) ||
    (locale === 'pt' && ARTIST_PROFILES_PT[name]) ||
    (locale === 'it' && ARTIST_PROFILES_IT[name]) ||
    (locale === 'fr' && ARTIST_PROFILES_FR[name]) ||
    (locale === 'es' && ARTIST_PROFILES_ES[name]) ||
    ARTIST_PROFILES[name]
  );
}

